{
  "request": {
    "law_id": "NRS-484B-768-1",
    "actor": "cycle_or_scooter_operator"
  },
  "law_record": {
    "text": "Except as otherwise provided in subsection 2, an operator of a bicycle, an electric bicycle or an electric scooter upon a roadway shall not turn from a direct course unless the movement may be made with reasonable safety and the operator gives an appropriate signal. The operator shall give the appropriate signal at least one time but is not required to give the signal continuously. An operator of a bicycle, an electric bicycle or an electric scooter is not required to give a signal if: (a) The bicycle, electric bicycle or electric scooter is in a designated turn lane; or (b) Safe operation of the bicycle, electric bicycle or electric scooter requires the operator to keep both hands on the bicycle, electric bicycle or electric scooter."
  },
  "canonical_parameter_rules": {
    "aliases": {
      "kin.speed": "ego_speed",
      "operating_speed": "ego_speed"
    },
